import { mapActions } from 'vuex';
export default {
  name: 'ProductFormModal',
  props: {
    modelValue: {
      type: Boolean,
      default: false
    }
  },
  emits: ['update:modelValue', 'creado'],
  data() {
    return {
      formValido: false,
      guardando: false,
      error: false,
      form: {
        nombre: '',
        marca: '',
        categoria: '',
        precio: null,
        descripcion: '',
        imagen: ''
      },
      reglas: {
        requerido: v => v !== null && v !== '' || 'Campo obligatorio',
        positivo: v => v > 0 || 'Debe ser mayor a 0'
      }
    };
  },
  computed: {
    abierto: {
      get() {
        return this.modelValue;
      },
      set(valor) {
        this.$emit('update:modelValue', valor);
      }
    }
  },
  methods: {
    ...mapActions('productos', ['crearProducto']),
    resetForm() {
      this.form = {
        nombre: '',
        marca: '',
        categoria: '',
        precio: null,
        descripcion: '',
        imagen: ''
      };
      this.error = false;
      if (this.$refs.formulario) this.$refs.formulario.resetValidation();
    },
    cancelar() {
      this.resetForm();
      this.abierto = false;
    },
    async agregar() {
      const {
        valid
      } = await this.$refs.formulario.validate();
      if (!valid) return;
      this.guardando = true;
      this.error = false;
      try {
        const nuevoProducto = {
          ...this.form,
          imagen: this.form.imagen || 'https://placehold.co/400x300?text=Producto',
          isDefault: false
        };
        const creado = await this.crearProducto(nuevoProducto);
        this.resetForm();
        this.abierto = false;
        this.$emit('creado', creado);
      } catch (err) {
        console.error('Error al crear producto:', err);
        this.error = true;
      } finally {
        this.guardando = false;
      }
    }
  }
};
